1	//! Best-effort redaction of secrets from text before it reaches an agent.
2	//!
3	//! Three helpers, all pure and dependency-free:
4	//!
5	//! - [`redact_secrets`](crate::redact::redact_secrets) replaces values you already know are secret (a token you
6	//!   loaded, a password you were given). It is exact and reliable for those values.
7	//! - [`redact_url_userinfo`](crate::redact::redact_url_userinfo) removes the `user:password@` part of any URL in a
8	//!   text, including JSON-escaped (`https:\/\/`) and percent-encoded (`https%3A%2F%2F`) URLs.
9	//! - [`redact_common_shapes`](crate::redact::redact_common_shapes) is the safety net
10	//!   [`DomainError::from_error`](crate::DomainError::from_error) applies: URL userinfo, the values of query-string and
11	//!   `key=value` pairs whose key names a secret (`token`, `api_key`, `password`, ...), and a few well-known token
12	//!   shapes (`ghp_`, `github_pat_`, `npm_`, `pypi-`, `Bearer`).
13	//!
14	//! **What this does not cover.** A secret that is not a known value, not in a URL, not in a `key=value` pair with a
15	//! telling key and not one of the listed token shapes passes through: a JSON field such as `"password": "x"`, a
16	//! password in a connection string without `://`, a cloud key with another prefix, an encoded or split value. These
17	//! helpers are a second line of defense after keeping secrets out of messages in the first place. "Redacted" here
18	//! means "we looked for these shapes", never "safe to show".
19	
20	/// What a redacted value is replaced with.
21	pub const REDACTED: &str = "[REDACTED]";
22	
23	/// Replaces every occurrence of each secret in `text` with [`REDACTED`].
24	///
25	/// Empty secrets are ignored. When one secret contains another, the longer one wins, so no part of it is left behind.
26	/// The text is scanned once, so the marker itself is never searched again and the result is stable if you redact it a
27	/// second time, unless a secret can match part of the marker (`RED`, `[`): then the second pass redacts the marker.
28	///
29	/// ```
30	/// use michi_core::redact::redact_secrets;
31	///
32	/// assert_eq!(redact_secrets("auth failed for sk-live-1", &["sk-live-1"]), "auth failed for [REDACTED]");
33	/// ```
34	#[must_use]
35	pub fn redact_secrets(text: &str, secrets: &[&str]) -> String {
36	    let mut secrets: Vec<&str> = secrets.iter().copied().filter(|s| !s.is_empty()).collect();
37	    if secrets.is_empty() {
38	        return text.to_owned();
39	    }
40	    secrets.sort_by_key(|s| std::cmp::Reverse(s.len()));
41	    let mut out = String::with_capacity(text.len());
42	    let mut rest = text;
43	    while let Some(c) = rest.chars().next() {
44	        if let Some(s) = secrets.iter().find(|s| rest.starts_with(**s)) {
45	            out.push_str(REDACTED);
46	            rest = &rest[s.len()..];
47	        } else {
48	            out.push(c);
49	            rest = &rest[c.len_utf8()..];
50	        }
51	    }
52	    out
53	}
54	
55	/// Replaces the `user:password@` part of every `scheme://…` URL in `text` with [`REDACTED`], keeping the rest.
56	///
57	/// A URL runs from its `://` to the next whitespace, quote, backtick, `<` or `>`. Inside it, everything up to the
58	/// **last** `@` counts as userinfo, so a password that contains `@` or `/` is removed whole. The cost is that a URL
59	/// with no userinfo but an `@` later in its path (`https://host/pkg@1.2`) loses its host and path up to that `@`;
60	/// over-redacting is the safe direction here. Bare email addresses are not URLs and are left alone.
61	///
62	/// Three more shapes are covered:
63	///
64	/// - The JSON-escaped separator `:\/\/` (PHP and Java encoders emit it, and error bodies echo it).
65	/// - The percent-encoded separator `%3A%2F%2F` (either case), where the userinfo ends at the last `@` or `%40`.
66	/// - A quote inside the password (`postgres://u:p"w@host/db`). A quote ends a URL, so when the part before it holds no
67	///   `@`, the text after the quote is searched for one, as long as no `/`, `\`, `?` or `#` comes first. The cost is
68	///   that `"https://host","k":"a@b"` is over-redacted up to the `@`.
69	///
70	/// ```
71	/// use michi_core::redact::redact_url_userinfo;
72	///
73	/// assert_eq!(
74	///     redact_url_userinfo("clone of REDACTED failed"),
75	///     "clone of https://[REDACTED]@github.com/o/r failed"
76	/// );
77	/// ```
78	#[must_use]
79	pub fn redact_url_userinfo(text: &str) -> String {
80	    settle(text, userinfo_pass)
81	}
82	
83	/// Runs `pass` until the text stops changing, so the result is a fixed point and redacting it again changes nothing.
84	///
85	/// One pass can expose a shape another pass then matches (a URL nested in a password, a marker beside a quote). Each
86	/// change replaces non-marker text with a marker, so this settles fast; the cap only bounds hostile input.
87	fn settle(text: &str, pass: fn(&str) -> String) -> String {
88	    const MAX_PASSES: usize = 8;
89	    let mut current = pass(text);
90	    for _ in 0..MAX_PASSES {
91	        let next = pass(&current);
92	        if next == current {
93	            break;
94	        }
95	        current = next;
96	    }
97	    current
98	}
99	
100	fn userinfo_pass(text: &str) -> String {
101	    let upper = text.to_ascii_uppercase();
102	    let mut out = String::with_capacity(text.len());
103	    let mut pos = 0;
104	    while let Some((i, len, encoded)) = next_separator(&upper, pos) {
105	        let start = i + len;
106	        out.push_str(&text[pos..start]);
107	        let tail = &text[start..];
108	        let end = tail.find(is_url_end).unwrap_or(tail.len());
109	        let found = last_at(&tail[..end], encoded).or_else(|| at_past_quote(tail, end, encoded)).filter(|at| *at > 0);
110	        match found {
111	            Some(at) => {
112	                out.push_str(REDACTED);
113	                // Resume at the `@`: the rest of the URL is kept and scanned for further URLs.
114	                pos = start + at;
115	            }
116	            // No userinfo here; keep scanning right after the separator, so a URL inside this one is still seen.
117	            None => pos = start,
118	        }
119	    }
120	    out.push_str(&text[pos..]);
121	    out
122	}
123	
124	/// The earliest URL separator at or after `from`: its byte offset, its length, and whether it is percent-encoded.
125	fn next_separator(upper: &str, from: usize) -> Option<(usize, usize, bool)> {
126	    const SEPARATORS: [(&str, bool); 3] = [("://", false), (":\\/\\/", false), ("%3A%2F%2F", true)];
127	    SEPARATORS
128	        .iter()
129	        // `upper` only changes ASCII letters, so its offsets are the text's; the separators are uppercase already.
130	        .filter_map(|(sep, encoded)| upper[from..].find(sep).map(|i| (from + i, sep.len(), *encoded)))
131	        .min_by_key(|(i, _, _)| *i)
132	}
133	
134	/// Offset of the last `@` (or, in a percent-encoded URL, `%40`) in `url`.
135	fn last_at(url: &str, encoded: bool) -> Option<usize> {
136	    let plain = url.rfind('@');
137	    if !encoded {
138	        return plain;
139	    }
140	    let pct = url.to_ascii_uppercase().rfind("%40");
141	    plain.max(pct)
142	}
143	
144	/// The first `@` after a quote that ended the URL at `end`, if nothing that ends an authority comes before it.
145	fn at_past_quote(tail: &str, end: usize, encoded: bool) -> Option<usize> {
146	    if !tail[end..].starts_with(['"', '\'']) {
147	        return None;
148	    }
149	    let region_end = tail.find(|c: char| c.is_whitespace() || matches!(c, '`' | '<' | '>')).unwrap_or(tail.len());
150	    let region = &tail[..region_end];
151	    let stop = region.find(['/', '\\', '?', '#']).unwrap_or(region.len());
152	    let candidate = &region[..stop];
153	    let at = if encoded { last_at(candidate, true) } else { candidate.find('@') };
154	    at.filter(|at| *at >= end)
155	}
156	
157	fn is_url_end(c: char) -> bool {
158	    c.is_whitespace() || matches!(c, '"' | '\'' | '`' | '<' | '>')
159	}
160	
161	/// The safety net for text copied from an error: URL userinfo ([`redact_url_userinfo`]), the values of `key=value`
162	/// pairs whose key names a secret, and well-known token shapes. Used by
163	/// [`DomainError::from_error`](crate::DomainError::from_error) and the pipeline's `ExecutionError` conversion.
164	///
165	/// Covered:
166	///
167	/// - Everything [`redact_url_userinfo`] covers.
168	/// - A value after `key=` (query string, form body, log line) when the key, lowercased with `-` read as `_`, is `key`,
169	///   `sig`, `auth`, `pwd`, ends in `_key`, `_sig` or `_auth`, starts with `auth_`, or contains `token`, `secret`,
170	///   `passw`, `signature`, `apikey`, `api_key`, `credential` or `authoriz`. The value runs to whitespace, `&`, a
171	///   quote, a backtick, `)`, `<` or `>`. Other keys (`page`, `status_code`, `monkey`) are kept.
172	/// - `ghp_`, `gho_`, `ghu_`, `ghs_`, `ghr_`, `github_pat_`, `npm_` and `pypi-` followed by at least 16 token
173	///   characters, and `Bearer ` (either case) followed by at least 16. A short lookalike (`pypi-mirror`) is kept.
174	///
175	/// Not covered: see the module docs. A match is a heuristic; this never makes text safe to show, it removes the
176	/// shapes that leaked in practice.
177	///
178	/// Redacting twice gives the same text as redacting once.
179	///
180	/// ```
181	/// use michi_core::redact::redact_common_shapes;
182	///
183	/// assert_eq!(
184	///     redact_common_shapes("GET https://api.x.com/v1?page=2&access_token=REDACTED failed"),
185	///     "GET https://api.x.com/v1?page=2&access_token=[REDACTED] failed"
186	/// );
187	/// ```
188	#[must_use]
189	pub fn redact_common_shapes(text: &str) -> String {
190	    settle(text, redact_pass)
191	}
192	
193	fn redact_pass(text: &str) -> String {
194	    // Token shapes first: a `Bearer` token inside `auth=Bearer xyz` would otherwise be left behind when the key=value
195	    // pass only takes the word after the `=`. Userinfo goes before the key=value pass so a `?` inside a password
196	    // cannot be read as a query.
197	    let shaped = redact_token_shapes(text);
198	    let userinfo = redact_url_userinfo(&shaped);
199	    redact_secret_pairs(&userinfo)
200	}
201	
202	/// Prefixes of well-known token formats, redacted whole.
203	const TOKEN_PREFIXES: [&str; 8] = ["github_pat_", "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "npm_", "pypi-"];
204	/// Fewest token characters after a prefix for it to count as a token and not a word.
205	const MIN_TOKEN_TAIL: usize = 16;
206	
207	fn is_token_char(c: char) -> bool {
208	    c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.' | '=' | '+' | '/' | '~')
209	}
210	
211	/// Length of the token characters at the start of `s`.
212	fn token_tail_len(s: &str) -> usize {
213	    s.find(|c: char| !is_token_char(c)).unwrap_or(s.len())
214	}
215	
216	fn redact_token_shapes(text: &str) -> String {
217	    let mut out = String::with_capacity(text.len());
218	    let mut pos = 0;
219	    let mut prev_alnum = false;
220	    for (i, c) in text.char_indices() {
221	        let at_boundary = !prev_alnum;
222	        prev_alnum = c.is_alphanumeric();
223	        if i < pos || !at_boundary {
224	            continue;
225	        }
226	        let rest = &text[i..];
227	        // `(prefix kept, token start)`: Bearer keeps its word, the other shapes are redacted whole.
228	        let hit = if let Some(word) = ["Bearer ", "bearer "].iter().find(|w| rest.starts_with(**w)) {
229	            Some((i + word.len(), i + word.len()))
230	        } else {
231	            TOKEN_PREFIXES.iter().find(|p| rest.starts_with(**p)).map(|p| (i, i + p.len()))
232	        };
233	        let Some((redact_from, tail_start)) = hit else { continue };
234	        let tail = token_tail_len(&text[tail_start..]);
235	        if tail < MIN_TOKEN_TAIL {
236	            continue;
237	        }
238	        out.push_str(&text[pos..redact_from]);
239	        out.push_str(REDACTED);
240	        pos = tail_start + tail;
241	    }
242	    out.push_str(&text[pos..]);
243	    out
244	}
245	
246	fn is_key_char(b: u8) -> bool {
247	    b.is_ascii_alphanumeric() || matches!(b, b'_' | b'-' | b'.')
248	}
249	
250	fn is_value_end(c: char) -> bool {
251	    c.is_whitespace() || matches!(c, '&' | '"' | '\'' | '`' | ')' | '<' | '>')
252	}
253	
254	fn is_secret_key(key: &str) -> bool {
255	    let key = key.to_ascii_lowercase().replace('-', "_");
256	    const CONTAINS: [&str; 8] =
257	        ["token", "secret", "passw", "signature", "apikey", "api_key", "credential", "authoriz"];
258	    CONTAINS.iter().any(|w| key.contains(w))
259	        || matches!(key.as_str(), "key" | "sig" | "auth" | "pwd")
260	        || key.ends_with("_key")
261	        || key.ends_with("_sig")
262	        || key.ends_with("_auth")
263	        || key.starts_with("auth_")
264	}
265	
266	fn redact_secret_pairs(text: &str) -> String {
267	    let bytes = text.as_bytes();
268	    let mut out = String::with_capacity(text.len());
269	    let mut pos = 0;
270	    let mut search = 0;
271	    while let Some(i) = text[search..].find('=').map(|i| search + i) {
272	        search = i + 1;
273	        let mut key_start = i;
274	        while key_start > pos && is_key_char(bytes[key_start - 1]) {
275	            key_start -= 1;
276	        }
277	        if key_start == i || !is_secret_key(&text[key_start..i]) {
278	            continue;
279	        }
280	        let value = &text[i + 1..];
281	        let len = value.find(is_value_end).unwrap_or(value.len());
282	        if len == 0 {
283	            continue;
284	        }
285	        out.push_str(&text[pos..=i]);
286	        out.push_str(REDACTED);
287	        pos = i + 1 + len;
288	        search = pos;
289	    }
290	    out.push_str(&text[pos..]);
291	    out
292	}
