fn a_json_escaped_url_is_redacted() {
    let out = redact_url_userinfo(r#"{"url":"https:\/\/bot:ghp_SECRET@github.com\/o\/r"}"#);
    assert!(!out.contains("ghp_SECRET"), "{out}");
    assert!(out.contains("github.com"), "the host is kept: {out}");
}

