    /// Redacting twice equals redacting once, for any text and for texts built from the leaky shapes.
    #[test]
    fn redaction_is_idempotent(text in "(\\PC|https?://|:\\\\/\\\\/|%3A%2F%2F|%40|@|\"|\\?|&|token=|sig=|Bearer |ghp_|[a-zA-Z0-9]{0,24}){0,12}") {
