        let Some((from, to)) = value_span(rest, line_value) else { continue };
        let value_start = search + blanks;
        out.push_str(&text[pos..value_start + from]);
        out.push_str(REDACTED);
        pos = value_start + to;
        search = pos;
    }
    out.push_str(&text[pos..]);
