    // Every scan below stops at a newline and is consumed by the value it finds, so a long text of `key="` pairs costs
    // one pass, not one pass per pair.
    let line_end = |s: &str| s.find(['\n', '\r']).unwrap_or(s.len());
    // An escaped quote (`\"`, JSON inside a JSON string) closes at the next `\"`.
    if let Some(inner) = rest.strip_prefix("\\\"") {
        let inner = &inner[..line_end(inner)];
        let end = inner.find("\\\"").unwrap_or(inner.len());
        return (end > 0).then_some((2, 2 + end));
    }
    if let Some(q) = rest.chars().next().filter(|c| matches!(c, '"' | '\'')) {
        let inner = &rest[1..];
        let inner = &inner[..line_end(inner)];
        let mut end = inner.len();
        let mut chars = inner.char_indices();
        while let Some((i, c)) = chars.next() {
            if c == '\\' {
                chars.next();
            } else if c == q {
                end = i;
                break;
            }
        }
        return (end > 0).then_some((1, 1 + end));
    }
    if line_value {
        let eol = line_end(rest);
        return (eol > 0).then_some((0, eol));
    }
