        })
        .min()
        .unwrap_or_default()
}

/// Times `work(n)` at `n` and `n * GROWTH`, building the input outside the timed region.
fn assert_linear<I>(label: &str, n: usize, build: impl Fn(usize) -> I, work: impl Fn(&I)) {
